import React from "react";
import _ from "lodash";

import "../assets/css/loading-page.css";

function LoadingPage(props) {
  let radius = 150;
  let bigRadius = 250;

  let width = 35;
  let height = 35;

  let numPoints = 10;

  let x = window.outerWidth / 2 - width / 2;
  let y = window.outerHeight / 2 - height / 2;

  return (
    <div className="loading-page-wrapper">
      <h1 className="loading-text-wrapper montserrat-light">loading</h1>
      {_.times(numPoints, n => {
        const angle = (n * (2 * Math.PI)) / numPoints;

        let offset = 10;

        const firstPointX = (radius + offset) * Math.cos(angle);
        const firstPointY = (radius + offset) * Math.sin(angle);
        const secondPointX = (bigRadius + offset) * Math.cos(angle);
        const secondPointY = (bigRadius + offset) * Math.sin(angle);

        const firstArcX = (Math.random() * div + radius) * Math.cos(angle);
        const firstArcY = (Math.random() * div + radius) * Math.sin(angle);
        const secondArcX =
          (Math.random() * div + radius) * Math.cos(angle + Math.PI);
        const secondArcY =
          (Math.random() * div + radius) * Math.sin(angle + Math.PI);

        return (
          <div
            className="circle"
            style={{
              offsetPath: `path("M ${x - firstArcX / 2},${
                y - firstArcY / 2
              } a ${radius},${radius} 0 1,0 ${firstArcX},${firstArcY} a ${radius},${radius} 0 1,0 ${secondArcX},${secondArcY}")`,
              animationDuration: Math.random(n) * 5
            }}
          ></div>
        );
      })}
    </div>
  );
}

export default LoadingPage;
